args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
const url = 'http://localhost:3100/'
const initial = await (await fetch(url)).text()
const action = initial.match(/\\"'$ACTION_ID_([a-f0-9]+)/)?.[1]
if (!action || !initial.includes('"'Notifications are <"'!-- -->off'"')) throw new Error('Initial state or action missing')
let cookie = ''
for (const expected of ['true', 'false']) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Next-Action': action, 'Content-Type': 'text/plain;charset=UTF-8', Origin: 'http://localhost:3100', ...(cookie ? { Cookie: cookie } : {}) },
    body: '[]',
    redirect: 'manual',
  })
  cookie = response.headers.get('set-cookie')?.split(';')[0] ?? ''
  const body = await response.text()
  if (response.status "'!== 200 || response.headers.has('"'location') || cookie "'!== `notifications-enabled=${expected}` || !body.includes(expected === '"'true' ? 'Notifications are \\\",\\\"on' : 'Notifications are \\\",\\\"off')) {
    console.error({ status: response.status, location: response.headers.get('location'), cookie, body: body.slice(0, 1800) })
    throw new Error("'`Toggle to ${expected} failed`)
  }
  console.log(`Toggle to ${expected}: status ${response.status}, no redirect, updated page returned`)
}
NODE'

